tools.mcp__git_bash__run({command:"git remote -v && git branch -vv && git rev-parse HEAD origin/HEAD && git status --short --branch && git diff --stat && git diff --cached --stat",description:"Verify origin upstream commit and working tree changes",workdir:"C:\\dev\\S-SHE"}),
tools.mcp__git_bash__run({command:"ls -la && git ls-remote --symref origin HEAD",description:"Verify repository files and current GitHub default commit",workdir:"C:\\dev\\S-SHE"})
]); results.forEach(text);

